param([Parameter(Mandatory=$true)][string]$EventsPath,[string]$CursorPath="$EventsPath.cursor")
$OutputEncoding=[Console]::OutputEncoding=[System.Text.UTF8Encoding]::new($false);$cursor=0;if(Test-Path -LiteralPath $CursorPath){[int]::TryParse((Get-Content -LiteralPath $CursorPath -Raw),[ref]$cursor)|Out-Null};if(!(Test-Path -LiteralPath $EventsPath)){Write-Host '等待事件文件';exit 0};$lines=@(Get-Content -LiteralPath $EventsPath -ErrorAction SilentlyContinue);for($i=$cursor;$i -lt $lines.Count;$i++){try{$lines[$i]|ConvertFrom-Json|ConvertTo-Json -Compress}catch{}};Set-Content -LiteralPath $CursorPath -Value $lines.Count -Encoding UTF8
